/**
 * DOMPurify Standalone Minimalist Sanitizer Bundle
 * Implements sanitize(dirty, config) adhering to ALLOWED_TAGS & ALLOWED_ATTR
 */
(function (global) {
  'use strict';

  var DOMPurify = {
    version: "3.1.7",
    isSupported: true,
    sanitize: function (dirty, config) {
      if (!dirty || typeof dirty !== 'string') return '';
      config = config || {};

      var allowedTags = config.ALLOWED_TAGS || ['p', 'br', 'strong', 'em', 'code', 'pre', 'ul', 'ol', 'li', 'span', 'h1', 'h2', 'h3', 'table', 'thead', 'tbody', 'tr', 'th', 'td', 'a'];
      var allowedAttr = config.ALLOWED_ATTR || ['href', 'class', 'target'];
      var uriRegExp = config.ALLOWED_URI_REGEXP || /^(?:(?:https?|mailto):)/i;

      var parser = new DOMParser();
      var doc = parser.parseFromString(dirty, 'text/html');

      function cleanNode(node) {
        var children = Array.from(node.childNodes);
        for (var i = 0; i < children.length; i++) {
          var child = children[i];
          if (child.nodeType === 1) { // ELEMENT_NODE
            var tagName = child.tagName.toLowerCase();
            if (allowedTags.indexOf(tagName) === -1) {
              // Strip disallowed tag
              child.remove();
              continue;
            }
            // Sanitize attributes
            var attrs = Array.from(child.attributes);
            for (var a = 0; a < attrs.length; a++) {
              var attrName = attrs[a].name.toLowerCase();
              var attrVal = attrs[a].value;
              if (allowedAttr.indexOf(attrName) === -1) {
                child.removeAttribute(attrName);
              } else if ((attrName === 'href' || attrName === 'src') && !uriRegExp.test(attrVal.trim())) {
                child.removeAttribute(attrName);
              }
            }
            cleanNode(child);
          } else if (child.nodeType === 3) { // TEXT_NODE
            // safe
          } else {
            child.remove();
          }
        }
      }

      cleanNode(doc.body);
      return doc.body.innerHTML;
    }
  };

  global.DOMPurify = DOMPurify;
})(typeof window !== 'undefined' ? window : this);
